const loopStages={observe:{label:"01 · OBSERVE",title:"Collect evidence without judging too quickly.",description:"Record the answer, response type, delay, retry count, and current activity. One response is evidence. It is not a permanent label.",input:"Child response + activity context",output:"Structured observation event",rule:"Keep raw evidence separate from skill estimates",color:"#899cf0"},estimate:{label:"02 · ESTIMATE",title:"Update a skill estimate by a small amount.",description:"Combine the new observation with prior evidence. Track both the estimated skill level and how confident the system is in that estimate.",input:"Prior state + new observation",output:"Updated skill and confidence",rule:"One answer must not create a large change",color:"#a48de5"},choose:{label:"03 · CHOOSE",title:"Select one reachable learning objective.",description:"Choose a task that is slightly beyond what appears easy, but still reachable with a hint. Respect the parent’s approved goals and the child’s current state.",input:"Learner state + approved goals",output:"Objective and difficulty",rule:"Prefer a small next step over a broad lesson",color:"#dca45a"},teach:{label:"04 · TEACH",title:"Deliver one short prompt with one clear goal.",description:"Use a reviewed activity template. Give one instruction, few choices, enough wait time, and a warm response that does not depend on praise alone.",input:"Objective + activity template",output:"Spoken prompt and visual choices",rule:"One instruction per turn",color:"#e2b061"},check:{label:"05 · CHECK",title:"Evaluate the task result, not the child.",description:"Compare the response with the activity’s expected evidence. Account for the response mode and any scaffold that the system provided.",input:"Response + expected evidence",output:"Outcome with context",rule:"Score the interaction, never the child",color:"#63b89c"},adapt:{label:"06 · ADAPT",title:"Change the next turn, not the whole profile.",description:"Make the next prompt easier, repeat at the same level with a variation, add a scaffold, switch response mode, or move one step harder.",input:"Outcome + learner state",output:"Next teaching action",rule:"Adapt one variable at a time",color:"#e1756e"}};
const loopTabs=[...document.querySelectorAll(".loop-tab")],loopLabel=document.querySelector("#loop-label"),loopTitle=document.querySelector("#loop-title"),loopDescription=document.querySelector("#loop-description"),loopInput=document.querySelector("#loop-input"),loopOutput=document.querySelector("#loop-output"),loopRule=document.querySelector("#loop-rule");
function showLoopStage(name){const stage=loopStages[name];if(!stage)return;loopTabs.forEach(tab=>{const active=tab.dataset.stage===name;tab.classList.toggle("is-active",active);tab.setAttribute("aria-pressed",String(active))});loopLabel.textContent=stage.label;loopLabel.style.color=stage.color;loopTitle.textContent=stage.title;loopDescription.textContent=stage.description;loopInput.textContent=stage.input;loopOutput.textContent=stage.output;loopRule.textContent=stage.rule}
loopTabs.forEach(tab=>tab.addEventListener("click",()=>showLoopStage(tab.dataset.stage)));
const scenarios={correct:{observe:"Child selects the cat.",estimate:"Positive evidence for animal matching.",next:"Confirm, then vary the example.",voice:"“Yes, that is the cat. Can you find another cat?”"},silence:{observe:"No response after the normal wait time.",estimate:"No skill conclusion. The cause is unknown.",next:"Reduce language and add a clear visual cue.",voice:"“Let’s look together. Is the cat here or here?”"},retry:{observe:"Two mismatches with the same format.",estimate:"The current task or response mode may be too hard.",next:"Model the answer, then use an easier contrast.",voice:"“This is the cat. Cat. Now, can you find the dog?”"}};
const scenarioTabs=[...document.querySelectorAll(".scenario-tab")],scenarioObserve=document.querySelector("#scenario-observe"),scenarioEstimate=document.querySelector("#scenario-estimate"),scenarioNext=document.querySelector("#scenario-next"),scenarioVoice=document.querySelector("#scenario-voice");
function showScenario(name){const scenario=scenarios[name];if(!scenario)return;scenarioTabs.forEach(tab=>{const active=tab.dataset.scenario===name;tab.classList.toggle("is-active",active);tab.setAttribute("aria-selected",String(active));tab.tabIndex=active?0:-1});scenarioObserve.textContent=scenario.observe;scenarioEstimate.textContent=scenario.estimate;scenarioNext.textContent=scenario.next;scenarioVoice.textContent=scenario.voice}
scenarioTabs.forEach((tab,index)=>{tab.addEventListener("click",()=>showScenario(tab.dataset.scenario));tab.addEventListener("keydown",event=>{if(!["ArrowLeft","ArrowRight"].includes(event.key))return;event.preventDefault();const direction=event.key==="ArrowRight"?1:-1;const next=scenarioTabs[(index+direction+scenarioTabs.length)%scenarioTabs.length];showScenario(next.dataset.scenario);next.focus()})});
const revealTargets=document.querySelectorAll(".section-heading, .system-map, .loop-board, .learner-layout, .scenario-shell, .safety-grid, .mvp-grid, .not-yet");
if("IntersectionObserver" in window&&!window.matchMedia("(prefers-reduced-motion: reduce)").matches){revealTargets.forEach(target=>target.classList.add("reveal"));const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;entry.target.classList.add("is-visible");observer.unobserve(entry.target)})},{threshold:.08});revealTargets.forEach(target=>observer.observe(target))}
